<?php
require dirname(__DIR__).'/vendor/autoload.php';
Dotenv\Dotenv::createImmutable(dirname(__DIR__))->safeLoad();
use App\Repositories\Connection;
use App\Services\MochiConciergeService;
use App\Services\MochiSessionService;
use App\Services\MochiOperationalToolsService;

$fail=[];$ok=static function(bool $condition,string $name)use(&$fail){echo ($condition?'PASS ':'FAIL ').$name.PHP_EOL;if(!$condition)$fail[]=$name;};
try{$db=new Connection();$db->beginTransaction();$db->query("SELECT id,id_owner,level,name,lastname FROM users WHERE level IN (1,4,5) ORDER BY FIELD(level,1,4,5)");$users=$db->fetchAll();$by=[];foreach($users as $u)$by[(int)$u->level]=$u;$admin=$by[1]??null;if(!$admin)throw new RuntimeException('No Level 1 QA user exists.');$owner=(int)$admin->id;
 $sessions=new MochiSessionService($owner,'vnvevents',$db);$a=$sessions->today((int)$admin->id,'2026-09-30');$b=$sessions->today((int)$admin->id,'2026-10-01');$sameDay=$sessions->today((int)$admin->id,'2026-10-01');$compatibleCreate=$sessions->create((int)$admin->id);$ok((int)$a->id!==(int)$b->id,'daily reset creates a new session');$ok((int)$sameDay->id===(int)$b->id,'calendar date keeps one conversation per day');$ok((string)$compatibleCreate->session_date===(new DateTimeImmutable('now',new DateTimeZone('America/New_York')))->format('Y-m-d'),'legacy new-chat action resolves to today instead of creating a duplicate');$ok(count($sessions->history((int)$admin->id))>=2,'daily history is retained');
 $tools=new MochiOperationalToolsService($owner,'vnvevents',$db);$ok(count($tools->suggestions(1))===4,'Level 1 has four suggestions');$ok(count($tools->suggestions(4))===4,'Level 4 has four suggestions');$ok(count($tools->suggestions(5))===4,'Level 5 has four suggestions');
 $ok($tools->select('Revisa el contrato: ¿cuánto tiempo antes debemos llegar para instalar?',1)==='contract_terms','contract clause questions do not open signature lists');
 $ok($tools->select('¿Cuántos contratos faltan por firmar?',1)==='contracts','contract signature questions keep the contract status route');
 $ok($tools->select('¿Cuántos Team Members activos tengo?',1)==='team_members','team member questions use the team roster');
 $ok($tools->select('¿Hay contradicciones entre los servicios del estimate y la tienda?',1)==='knowledge_audit','catalog consistency questions use the knowledge audit');
 $ok($tools->select('¿Cuál es el evento más grande de noviembre?',1)==='largest_event','largest event questions use period analytics');
 $ok($tools->select('¿En cuántos eventos trabajó Oscar este año?',1)==='team_activity','employee event questions use assignment analytics');
 $ok($tools->select('¿Cuántas horas hizo Oscar esta semana?',1)==='payroll_hours','employee hour questions use payroll analytics');
 $ok($tools->select('¿Cuál ha sido el empleado al que más dinero le hemos pagado este año?',1)==='payroll_payments','employee payment questions use payroll payment history');
 $ok($tools->select('¿Cuántos leads activos tenemos en el CRM?',1)==='crm','CRM questions use the CRM source');
 $ok($tools->select('¿Dónde tengo las flores blancas?',1)==='warehouse','inventory location questions use Storage');
 $ok($tools->select('Muéstrame los estimados que se crearon el 26 de octubre de 2026',1)==='estimates','estimate creation-date questions use the dedicated estimate reader');
 foreach(['weekend_events','crm','collections','estimates','opportunities','requests','contracts','contract_terms','team_members','catalog','knowledge_audit','warehouse','website'] as $tool){$query=in_array($tool,['catalog','knowledge_audit'],true)?'Pasta Station':($tool==='team_members'?'solo los activos':($tool==='warehouse'?'¿Dónde tengo las flores blancas?':($tool==='estimates'?'Muéstrame los estimados que se crearon el 26 de octubre de 2026':'')));$result=$tools->run($tool,(int)$admin->id,1,(int)$b->id,$query);$ok(isset($result['reply'],$result['items']),'Level 1 tool '.$tool);if($tool==='estimates'){$ok(($result['facts']['created_start']??'')==='2026-10-26 00:00:00','estimate reader preserves the requested creation date');$ok(($result['facts']['created_end_exclusive']??'')==='2026-10-27 00:00:00','estimate reader uses a safe exclusive end bound');}}
 $estimateRead=(new MochiConciergeService($owner,'vnvevents',$db))->ask((int)$admin->id,1,'Muéstrame los estimados que se crearon el 26 de octubre de 2026 por favor');$ok(($estimateRead['tool']??'')==='estimates','the real Mochi chat bypasses estimate editing and returns the created-estimate reader');
 $teamUser=$by[4]??null;$teamName=$teamUser?trim((string)($teamUser->name??'').' '.(string)($teamUser->lastname??'')):'';
 foreach(['largest_event'=>'¿Cuál es el evento más grande de noviembre de 2026?','team_activity'=>'¿En cuántos eventos trabajó '.$teamName.' este año 2026?','payroll_hours'=>'¿Cuántas horas registró '.$teamName.' este año 2026?'] as $tool=>$query){if($tool!=='largest_event'&&!$teamUser)continue;$result=$tools->run($tool,(int)$admin->id,1,(int)$b->id,$query);$ok(isset($result['reply'],$result['items'],$result['facts']),'Level 1 analytic tool '.$tool);}
 $payroll=$tools->run('payroll_payments',(int)$admin->id,1,(int)$b->id,'¿Cuál ha sido el empleado al que más dinero le hemos pagado este año 2026?');$ok(isset($payroll['facts']['top_employee_name'],$payroll['facts']['top_calculated_amount']),'payroll payment ranking is calculated from payment history');
 $warehouse=$tools->run('warehouse',(int)$admin->id,1,(int)$b->id,'¿Dónde tengo las flores blancas?');$ok(str_contains(mb_strtolower((string)($warehouse['facts']['best_match']??'')),'white flowers'),'Storage finds the white-flowers container');
 $grazing=$tools->run('catalog',(int)$admin->id,1,(int)$b->id,'ok, cuanto vale un grazing table?');$grazingServices=$grazing['facts']['estimate_services']??[];$ok(count($grazingServices)===1&&($grazingServices[0]['name']??'')==='Grazing Table'&&abs((float)($grazingServices[0]['price']??0)-450.0)<0.001,'estimate catalog answers Grazing Table price without a public page');
 if(isset($by[4])){try{$tools->run('collections',(int)$by[4]->id,4,(int)$b->id);$ok(false,'Level 4 financial denial');}catch(Throwable){$ok(true,'Level 4 financial denial');}}
 if(isset($by[5])){try{$tools->run('weekend_events',(int)$by[5]->id,5,(int)$b->id);$ok(false,'Level 5 all-event denial');}catch(Throwable){$ok(true,'Level 5 all-event denial');}}
 $db->query("SELECT id,name,price FROM store_products WHERE id_owner=:owner AND site_key='vnvevents' AND status='ACTIVE' AND is_public=1 AND product_type='FIXED' AND COALESCE(promo_price,0)=0 LIMIT 1");$db->bind(':owner',$owner);$p=$db->fetchOne();if($p){$before=$tools->run('catalog',(int)$admin->id,1,(int)$b->id,(string)$p->name);$db->query('UPDATE store_products SET price=price+1 WHERE id=:id');$db->bind(':id',(int)$p->id);$db->execute();$after=$tools->run('catalog',(int)$admin->id,1,(int)$b->id,(string)$p->name);$ok(json_encode($before)!==json_encode($after),'catalog reflects transactional price change');}
 $db->rollback();
}catch(Throwable $e){$fail[]=$e->getMessage();echo 'FAIL '.$e->getMessage().PHP_EOL;try{if(isset($db))$db->rollback();}catch(Throwable){}}
echo $fail?"MOCHI LOCAL QA FAILED — DO NOT DEPLOY\n":"MOCHI LOCAL QA PASSED — READY FOR PRODUCTION\n";exit($fail?1:0);
